[external_agent_tool_call: PowerShell]
description: Fix remaining stale figures
command: python -c "
import docx
p=r'Z:\00. Proiecte 2025\2023.05.01 IndustryDeveloperPrinter\Server AI\01 - Oferta Tehnico-Comerciala si BOM - TITAN-12 Blackwell AI Rack System (preturi si linkuri RO-EU) v3.0.docx'
d=docx.Document(p)
REP={'631.477 RON':'636.025 RON','5,08 RON':'5,2644 RON','curs 5,08':'curs 5,2644'}
def fix(par):
    t=''.join(r.text for r in par.runs)
    if not t: return 0
    n=t
    for k,v in REP.items(): n=n.replace(k,v)
    if n==t: return 0
    par.runs[0].text=n
    for r in par.runs[1:]: r.text=''
    return 1
c=0
for par in d.paragraphs: c+=fix(par)
for t in d.tables:
    for row in t.rows:
        for cell in row.cells:
            for par in cell.paragraphs: c+=fix(par)
d.save(p); print('fixed',c)
" 2>$null
[/external_agent_tool_call]

